CREATE COLUMN TABLE "TEST_AP"."OERT" ("NumTypeId" INTEGER CS_INT NOT NULL , "NumTypeNam" NVARCHAR(30) NOT NULL , "FirstNum" INTEGER CS_INT, "NextNum" INTEGER CS_INT, "LastNum" INTEGER CS_INT, PRIMARY KEY ("NumTypeId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OERT_TYPE_NAME" ON "TEST_AP"."OERT" ( "NumTypeNam" ASC )